fn int_to_str(mut_x: Int) -> Str {
    let mut_chars = vec()
    while mut_x != 0 {
        let mut_digit = mut_x % 10
        mut_x = trunc(mut_x / 10)
        push(mut_chars, int_to_str(mut_digit))
    }
    let mut_result = str()
    for mut_ch in &mut_chars {
        mut_result = concat(mut_ch, mut_result)
    }
    if mut_result == str() {
        mut_result = str("0")
    }
    mut_result
}

fn print_str(s: Str) {
    for mut_ch in chars(s) {
        print_ch(mut_ch)
    }
}

fn print_ch(mut_ch: Str) {
    let mut_num = int_to_str(str_len(mut_ch))
    let mut_digit = mut_num % 10
    mut_num = trunc(mut_num / 10)
    print_str(int_to_str(mut_digit))
