    let mut_digit = mut_num % 10
    mut_num = trunc(mut_num / 10)
    print_str(int_to_str(mut_digit))
    print_str(mut_ch)
}

fn concat(a: Str, b: Str) -> Str {
    let mut_result = a
    for mut_ch in chars(b) {
        mut_result = concat(mut_result, mut_ch)
    }
    mut_result
}

fn chars(s: Str) -> Vec<Str> {
    let mut_result = vec()
    let mut_cursor = 0
    let mut_top = 0
    let mut_bottom = str_len(s) - 1
    while mut_cursor <= mut_top && mut_cursor <= mut_bottom {
        if s.chars().nth(mut_cursor) == s.chars().nth(mut_bottom) {
            push(mut_result, str(&s).substring(mut_cursor, mut_cursor + 1))
            mut_cursor = mut_cursor + 1
            mut_bottom = mut_bottom - 1
        } else if s.chars().nth(mut_cursor) == s.chars().nth(mut_top) {
            push(mut_result, str(&s).substring(mut_cursor, mut_cursor + 1))
            mut_cursor = mut_cursor + 1
            mut_top = mut_top - 1
        } else {
            break
        }
    }
    mut_result
}

fn str(s: &Vec<Str>) -> Str {
    let mut_result = str()
    for mut_ch in s {
        mut_result = concat(mut_result, mut_ch)
    }
    mut_result
}

fn str(s: &Vec<Str>, start: Int, end: Int) -> Str {
    let mut_result = str()
    for mut_ch in s.iter().cloned().take(end - start + 1).skip(start) {
        mut_result = concat(mut_result, mut_ch)
    }
    mut_result
}

fn str(s: &Vec<Str>, start: Int) -> Str {
    let mut_result = str()
    for mut_ch in s.iter().cloned().take(str_len(s) - start + 1).skip(start) {
        mut_result = concat(mut_result, mut_ch)
